ist() ([]Todo, error) {\n71: \trows, err := s.db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos ORDER BY id`)\n72: \tif err != nil {\n73: \t\treturn nil, fmt.Errorf(\"list todos: %w\", err)\n74: \t}\n75: \tdefer rows.Close()\n76: \n77: \ttodos := make([]Todo, 0)\n78: \tfor rows.Next() {\n79: \t\ttodo, err := scanTodo(rows)\n80: \t\tif err != nil {\n81: \t\t\treturn nil, err\n82: \t\t}\n83: \t\ttodos = append(todos, todo)\n84: \t}\n85: \tif err := rows.Err(); err != nil {\n86: \t\treturn nil, fmt.Errorf(\"iterate todos: %w\", err)\n87: \t}\n88: \treturn todos, nil\n89: }\n90: \n91: func (s *Store) Get(id int64) (Todo, error) {\n92: \trow := s.db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id)\n93: \ttodo, err := scanTodo(row)\n94: \tif errors.Is(err, sql.ErrNoRows) {\n95: \t\treturn Todo{}, errTodoNotFound\n96: \t}\n97: \treturn todo, err\n98: }\n99: \n100: func (s *Store) Create(input todoInput) (Todo, error) {\n101: \ttitle := strings.TrimSpace(input.Title)\n102: \tif title == \"\" {\n103: \t\treturn Todo{}, errTitleRequired\n104: \t}\n105: \n106: \tnow := time.Now().UTC()\n107: \tresult, err := s.db.Exec(\n108: \t\t`INSERT INTO todos (title, completed, created_at, updated_at) VALUES (?, ?, ?, ?)`,\n109: \t\ttitle,\n110: \t\tinput.Completed,\n111: \t\tnow.Format(time.RFC3339Nano),\n112: \t\tnow.Format(time.RFC3339Nano),\n113: \t)\n114: \tif err != nil {\n115: \t\treturn Todo{}, fmt.Errorf(\"create todo: %w\", err)\n116: \t}\n117: \tid, err := result.LastInsertId()\n118: \tif err != nil {\n119: \t\treturn Todo{}, fmt.Errorf(\"read created todo id: %w\", err)\n120: \t}\n121: \treturn Todo{\n122: \t\tID:        id,\n123: \t\tTitle:     title,\n124: \t\tCompleted: input.Completed,\n125: \t\tCreatedAt: now,\n126: \t\tUpdatedAt: now,\n127: \t}, nil\n128: }\n129: \n130: func (s *Store) Update(id int64, input todoInput) (Todo, error) {\n131: \ttitle := strings.TrimSpace(input.Title)\n132: \tif title == \"\"